"""Grounded, deterministic buyer brief. No prices or promises generated by an LLM."""
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from typing import Any

from .schemas import CapabilityMatch, CatalogReference, RequirementProperty

DETAIL_KEYS = ("business_kind", "product_types", "complexity", "material_grades", "limitations",
               "packaging", "delivery", "quality_control", "trial_batch")
NON_TECHNICAL = {"quantity_units", "budget_rub", "lead_time_days", "delivery_city"}


def confirmed_values(properties: list[RequirementProperty]) -> dict[str, Any]:
    return {p.key: p.value for p in properties if p.status == "confirmed" and p.value is not None}


def positive_integer(value: Any) -> int | None:
    try:
        number = Decimal(str(value))
        return int(number) if number.is_finite() and number > 0 and number == number.to_integral_value() else None
    except (InvalidOperation, ValueError, TypeError):
        return None


def catalog_reference(product: dict, properties: list[RequirementProperty], cautions: list[str]) -> CatalogReference:
    values = confirmed_values(properties)
    quantity = positive_integer(values.get("quantity_units"))
    price = Decimal(str(product["price_rub"]))
    for tier in sorted(product.get("price_tiers") or [], key=lambda item: item["min_units"]):
        if quantity is not None and quantity >= tier["min_units"]:
            price = Decimal(str(tier["unit_price_rub"]))
    characteristics = dict(product.get("characteristics") or {})
    if "inner_coating" not in characteristics and "coating" in characteristics:
        characteristics["inner_coating"] = characteristics["coating"]
    technical = {key: value for key, value in values.items() if key not in NON_TECHNICAL}
    # Exact matches only. Unknown, conflicting and qualitative requirements need human review.
    def equal(left: Any, right: Any) -> bool:
        return str(left).strip().casefold() == str(right).strip().casefold()
    comparable = bool(quantity and quantity >= product["moq_units"] and technical and not cautions
                      and all(p.status == "confirmed" for p in properties)
                      and all(key in characteristics and equal(value, characteristics[key]) for key, value in technical.items()))
    constraint_notes = []
    requested_days = positive_integer(values.get("lead_time_days"))
    if requested_days is not None and product["lead_time_days"] > requested_days:
        comparable = False
        constraint_notes.append("Заявленный срок превышает срок запроса.")
    if quantity and "budget_rub" in values:
        try:
            budget = Decimal(str(values["budget_rub"]))
            if not budget.is_finite() or budget <= 0 or price * quantity > budget:
                comparable = False
                constraint_notes.append("Стоимость товара не укладывается в указанный бюджет или бюджет требует уточнения.")
        except InvalidOperation:
            comparable = False
            constraint_notes.append("Бюджет требует уточнения.")
    total = (price * quantity).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP) if comparable else None
    return CatalogReference(
        product_id=product["id"], name=product["name"], unit_price_rub=str(price),
        total_rub=str(total) if total is not None else None, moq_units=product["moq_units"],
        lead_time_days=product["lead_time_days"], comparable=comparable,
        note=("Совпали заполненные характеристики и MOQ. Цена товара без доставки и дополнительных работ; наличие и срок подтвердит поставщик."
              if comparable else "Справочная карточка категории, не готовое предложение: характеристики, MOQ и условия требуют согласования. " + " ".join(constraint_notes)),
    )


def buyer_summary(matches: list[CapabilityMatch], unresolved: bool) -> str:
    if not matches:
        return ("По заполненным паспортам кандидаты не найдены. Это не означает, что заказ невозможен: "
                "уточните характеристики или опубликуйте потребность для ответа производителей.")
    result = f"Показано кандидатов по паспортам: {len(matches)} (не более 10). Это предварительный подбор, а не подтверждение заказа. "
    comparable = [(match, item) for match in matches for item in match.catalog if item.comparable and item.total_rub is not None]
    if comparable and not unresolved:
        cheapest_match, cheapest = min(comparable, key=lambda pair: Decimal(pair[1].total_rub))
        fastest_match, fastest = min(comparable, key=lambda pair: pair[1].lead_time_days)
        result += (f"Среди показанных карточек с совпавшими заполненными характеристиками: "
                   f"минимальная стоимость товара — {cheapest.total_rub} ₽ ({cheapest_match.company_name}); "
                   f"минимальный заявленный срок — {fastest.lead_time_days} дн. ({fastest_match.company_name}). "
                   "Доставка и дополнительные работы не включены; итоговую выгоду пока не рассчитываем.")
    else:
        result += "Данных для корректного сравнения полной цены и скорости недостаточно. Посмотрите ограничения и запросите условия у кандидатов."
    if unresolved:
        result += " Сначала разрешите противоречия и ответьте на вопросы; подбор обновится после уточнений."
    return result
